1	/**
2	 * Session rows for the cookie-based auth: create, look up by token hash, revoke.
3	 */
4	import { eq, lt } from "drizzle-orm";
5	import { newId } from "@/lib/id";
6	import { getDb, sessions, users } from "@/server/db";
7	import { toIsoTimestamp } from "@/types/common";
8	import { brandId, brandStamp } from "./_mappers";
9	import type {
10	  IsoTimestamp,
11	  OrgId,
12	  SessionId,
13	  UserId,
14	} from "@/types/common";
15	import type { SessionPrincipal } from "@/types/member";
16	
17	/**
18	 * Sessions are global rather than tenant-scoped: one cookie can move between
19	 * organizations via `activeOrgId`, and `SessionService` resolves the `Actor`
20	 * for whichever org the request addresses.
21	 */
22	export async function createSession(
23	  userId: UserId,
24	  tokenHash: string,
25	  expiresAt: IsoTimestamp,
26	): Promise<SessionPrincipal> {
27	  const stamp = toIsoTimestamp(new Date());
28	  const user = getDb().select().from(users).where(eq(users.id, userId)).get();
29	  if (!user) throw new Error(`User ${userId} not found`);
30	
31	  getDb()
32	    .insert(sessions)
33	    .values({
34	      id: newId(),
35	      userId,
36	      activeOrgId: null,
37	      tokenHash,
38	      expiresAt,
39	      createdAt: stamp,
40	      updatedAt: stamp,
41	    })
42	    .run();
43	
44	  return {
45	    userId,
46	    email: user.email,
47	    activeOrgId: null,
48	    expiresAt,
49	  };
50	}
51	
52	/** Expired rows resolve to `null` rather than being returned and re-checked. */
53	export async function findSessionByTokenHash(
54	  tokenHash: string,
55	): Promise<SessionPrincipal | null> {
56	  const row = getDb()
57	    .select({ session: sessions, user: users })
58	    .from(sessions)
59	    .innerJoin(users, eq(users.id, sessions.userId))
60	    .where(eq(sessions.tokenHash, tokenHash))
61	    .get();
62	
63	  if (!row) return null;
64	  if (row.session.expiresAt <= new Date().toISOString()) return null;
65	
66	  return {
67	    userId: brandId<UserId>(row.session.userId),
68	    email: row.user.email,
69	    activeOrgId:
70	      row.session.activeOrgId === null
71	        ? null
72	        : brandId<OrgId>(row.session.activeOrgId),
73	    expiresAt: brandStamp(row.session.expiresAt),
74	  };
75	}
76	
77	export async function setActiveOrg(
78	  sessionId: SessionId,
79	  orgId: OrgId,
80	): Promise<void> {
81	  getDb()
82	    .update(sessions)
83	    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
84	    .where(eq(sessions.id, sessionId))
85	    .run();
86	}
87	
88	export async function revokeSession(sessionId: SessionId): Promise<void> {
89	  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
90	}
91	
92	/**
93	 * Housekeeping sweep; returns how many rows it removed. A row that predates
94	 * the sweep is stale by definition — the cookie is re-issued on every sign-in,
95	 * so anything older than `now` has been superseded.
96	 */
97	export async function purgeExpiredSessions(
98	  now: IsoTimestamp,
99	): Promise<number> {
100	  const rows = getDb()
101	    .delete(sessions)
102	    .where(lt(sessions.createdAt, now))
103	    .returning({ id: sessions.id })
104	    .all();
105	  return rows.length;
106	}
107

