 * Sentinel org id for rate limits consumed before any tenant is known (login,
 * password reset, inbound webhooks). Re-exported as `ANONYMOUS_ORG_ID` from
 * the actions layer so every unauthenticated caller charges the same bucket;
 * `src/server` code that cannot import from `src/actions` uses this directly.
 */
export const ANONYMOUS_ORG_ID = "" as OrgId;

/**
 * Per-account rate-limit key: two different addresses must never share a
 * bucket, and the same address must always hash to the same bucket regardless
 * of how it was capitalized.
 */
export function accountRateLimitKey(email: string): OrgId {
